using System;
using System.IO;
using System.Linq;
using System.Globalization;
using System.Collections.Generic;
public sealed class CalendarEvent {
 public string id="",title="",date="",time="09:00",project="",notes="",lastReminder="";public int duration=60,remindMinutes=15;
}
internal sealed class DueReminder {internal string Title,Text,Key;internal WorkTask Task;internal CalendarEvent Event;internal DateTime At;internal void Mark(){if(Task!=null)Task.lastReminder=Key;else Event.lastReminder=Key;}}
internal static class Schedule {
 internal static DateTime Day(string date){return DateTime.ParseExact(date,"yyyy-MM-dd",CultureInfo.InvariantCulture);}
 internal static bool ValidTime(string time){DateTime parsed;return DateTime.TryParseExact(time,"HH:mm",CultureInfo.InvariantCulture,DateTimeStyles.None,out parsed);}
 internal static DateTime At(string date,string time){return Day(date).Add(TimeSpan.ParseExact(String.IsNullOrEmpty(time)?"09:00":time,"hh\\:mm",CultureInfo.InvariantCulture));}
 internal static readonly int[] Leads={-1,0,5,15,30,60,1440};
 internal static void Validate(Data data){if(data.events==null)data.events=new List<CalendarEvent>();if(data.events.Count>10000)throw new InvalidDataException("Trop de rendez-vous.");var ids=new HashSet<string>();foreach(var e in data.events){DateTime parsed;if(e==null||String.IsNullOrWhiteSpace(e.title)||e.title.Length>200||!DateTime.TryParseExact(e.date,"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out parsed)||!ValidTime(e.time)||e.duration<5||e.duration>1440||!Leads.Contains(e.remindMinutes)||(e.notes??"").Length>10000||(e.project??"").Length>80)throw new InvalidDataException("Rendez-vous invalide.");if(String.IsNullOrEmpty(e.id)||!ids.Add(e.id)){e.id=Guid.NewGuid().ToString();ids.Add(e.id);}e.notes=e.notes??"";e.project=e.project??"";}foreach(var t in data.tasks){if(t==null)continue;t.repeat=t.repeat??"none";t.dueTime=t.dueTime??"";if(!new[]{"none","daily","weekly","monthly"}.Contains(t.repeat)||(!String.IsNullOrEmpty(t.dueTime)&&!ValidTime(t.dueTime))||!Leads.Contains(t.remindMinutes)||(t.repeat!="none"&&String.IsNullOrEmpty(t.due))||(t.remindMinutes>=0&&String.IsNullOrEmpty(t.due)))throw new InvalidDataException("Date, récurrence ou rappel de tâche invalide.");if(t.repeatDay<1||t.repeatDay>31)t.repeatDay=String.IsNullOrEmpty(t.due)?1:Day(t.due).Day;}}
 internal static DateTime NextDate(WorkTask task){var day=Day(task.due);if(task.repeat=="daily")return day.AddDays(1);if(task.repeat=="weekly")return day.AddDays(7);var month=day.AddMonths(1);return new DateTime(month.Year,month.Month,Math.Min(task.repeatDay,DateTime.DaysInMonth(month.Year,month.Month)));}
 internal static void Complete(Data data,WorkTask task){if(task.status!="done"||String.IsNullOrEmpty(task.completedOn))task.completedOn=DateTime.Today.ToString("yyyy-MM-dd");task.status="done";if(task.repeat=="none"||String.IsNullOrEmpty(task.repeat)||String.IsNullOrEmpty(task.due)||!String.IsNullOrEmpty(task.nextId))return;var next=NextDate(task);task.nextId=Guid.NewGuid().ToString();data.tasks.Add(new WorkTask{id=task.nextId,title=task.title,project=task.project,priority=task.priority,status="todo",notes=task.notes,due=next.ToString("yyyy-MM-dd"),dueTime=task.dueTime,repeat=task.repeat,repeatDay=task.repeatDay,remindMinutes=task.remindMinutes});}
 internal static List<DueReminder> Due(Data data,DateTime now){var due=new List<DueReminder>();foreach(var t in data.tasks.Where(t=>t.status!="done"&&t.remindMinutes>=0&&!String.IsNullOrEmpty(t.due))){var at=At(t.due,t.dueTime);string key=at.ToString("yyyyMMddHHmm")+"/"+t.remindMinutes;if(t.lastReminder!=key&&now>=at.AddMinutes(-t.remindMinutes)&&now-at.AddMinutes(-t.remindMinutes)<=TimeSpan.FromDays(1))due.Add(new DueReminder{Title=t.title,Text="Tâche · "+at.ToString("dd/MM HH:mm"),Key=key,At=at,Task=t});}foreach(var e in data.events.Where(e=>e.remindMinutes>=0)){var at=At(e.date,e.time);string key=at.ToString("yyyyMMddHHmm")+"/"+e.remindMinutes;if(e.lastReminder!=key&&now>=at.AddMinutes(-e.remindMinutes)&&now-at.AddMinutes(-e.remindMinutes)<=TimeSpan.FromDays(1))due.Add(new DueReminder{Title=e.title,Text="Rendez-vous · "+at.ToString("dd/MM HH:mm"),Key=key,At=at,Event=e});}return due.OrderBy(r=>r.At).ToList();}
 internal static void Test(string folder){var data=new Data();var task=new WorkTask{id="monthly",title="Fin du mois",project="Personnel",priority="Normale",status="todo",notes="",due="2028-01-31",repeat="monthly",repeatDay=31,dueTime="10:00",remindMinutes=15};data.tasks.Add(task);Store.Validate(data);Complete(data,task);var feb=data.tasks.Last();if(feb.due!="2028-02-29")throw new Exception("Mois bissextile");Complete(data,task);if(data.tasks.Count!=2)throw new Exception("Récurrence dupliquée");Complete(data,feb);if(data.tasks.Last().due!="2028-03-31")throw new Exception("Ancre mensuelle perdue");var next=data.tasks.Last();next.repeat="weekly";if(NextDate(next)!=new DateTime(2028,4,7))throw new Exception("Récurrence hebdomadaire");next.repeat="daily";if(NextDate(next)!=new DateTime(2028,4,1))throw new Exception("Récurrence quotidienne");var now=new DateTime(2028,3,31,9,45,0);if(Due(data,now).Count!=1||Due(data,now.AddMinutes(-1)).Count!=0)throw new Exception("Déclenchement rappel");Due(data,now)[0].Mark();if(Due(data,now).Count!=0)throw new Exception("Rappel dupliqué");data.events.Add(new CalendarEvent{id="event",title="RDV",date="2028-03-31",time="10:00",remindMinutes=15});if(Due(data,now).Count!=1||Due(data,now.AddDays(2)).Count!=0)throw new Exception("Rappel RDV ou rattrapage");var store=new Store(Path.Combine(folder,"agenda"));store.Value=data;store.Save();store=new Store(store.Root);if(store.Value.events.Count!=1||store.Value.tasks.Last().lastReminder!=next.lastReminder)throw new Exception("Persistance agenda");store.Export(Path.Combine(folder,"agenda-export.json"));store.Value.events.Clear();store.Import(Path.Combine(folder,"agenda-export.json"));if(store.Value.events.Count!=1)throw new Exception("Import agenda");bool bad=false;try{store.Value.events[0].time="25:90";Store.Validate(store.Value);}catch(InvalidDataException){bad=true;}if(!bad)throw new Exception("Heure invalide acceptée");var legacy=new Data();Store.Validate(legacy);if(legacy.events==null)throw new Exception("Migration agenda");}
}
